@page "/settings"
@rendermode InteractiveServer
@using sv_fce9d96ce083410f87948881c81a6a9f.Services
@using sv_fce9d96ce083410f87948881c81a6a9f.Models
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar" role="tablist" aria-label="Settings sections">
        @foreach (var section in _sections)
        {
            <button class="sidebar-tab @(ActiveSection == section.Key ? "active" : "")"
                    role="tab"
                    aria-selected="@(ActiveSection == section.Key)"
                    @onclick="() => SetActiveSection(section.Key)">
                <span class="tab-icon">@section.Icon</span>
                <span class="tab-label">@section.Label</span>
            </button>
        }
    </nav>

    <div class="settings-content" role="tabpanel">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner"></div>
                <p>Loading settings…</p>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    <ProfileSection Profile="_profile"
                                    SavedProfile="_savedProfile"
                                    OnSave="SaveProfile"
                                    OnDiscard="DiscardProfile" />
                    break;

                case "notifications":
                    <NotificationsSection Prefs="_notifPrefs"
                                          AllChannels="_allChannels"
                                          OnSave="SaveNotificationPrefs" />
                    break;

                case "security":
                    <SecuritySection Security="_security"
                                     CurrentSessionId="@_currentSessionId"
                                     OnChangePassword="ChangePassword"
                                     OnRevokeSession="RevokeSession"
                                     OnToggle2FA="Toggle2FA" />
                    break;

                case "appearance":
                    <AppearanceSection Appearance="_appearance"
                                       OnSave="SaveAppearance" />
                    break;
            }
        }
    </div>
</div>

@if (_toast is not null)
{
    <div class="toast-message @_toast.CssClass" role="alert">
        <span>@_toast.Message</span>
    </div>
}

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    private UserProfile _profile = null!;
    private UserProfile _savedProfile = null!;
    private NotificationPrefs _notifPrefs = null!;
    private SecuritySettings _security = null!;
    private AppearanceSettings _appearance = null!;
    private string _currentSessionId = "sess-1";

    private readonly List<string> _allChannels = ["general", "random", "announcements", "engineering", "design"];

    private ToastInfo? _toast;
    private CancellationTokenSource? _toastCts;

    private record SectionDef(string Key, string Label, string Icon);

    private static readonly SectionDef[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    ];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllAsync();
        _loading = false;
    }

    private async Task LoadAllAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _profile = profileTask.Result;
        _savedProfile = _profile;
        _notifPrefs = notifTask.Result;
        _security = securityTask.Result;
        _appearance = appearanceTask.Result;
    }

    private void SetActiveSection(string section)
    {
        ActiveSection = section;
    }

    private async Task SaveProfile(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!", true);
    }

    private void DiscardProfile()
    {
        _profile = _savedProfile;
    }

    private async Task SaveNotificationPrefs(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notifPrefs = prefs;
        await ShowToast("Notification preferences saved!", true);
    }

    private async Task ChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _security = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!", true);
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Session revoked.", true);
    }

    private async Task Toggle2FA(bool enabled)
    {
        // In a real app this would call the service
        _security = _security with { TwoFactorEnabled = enabled };
        await ShowToast(enabled ? "Two-factor authentication enabled." : "Two-factor authentication disabled.", true);
    }

    private async Task SaveAppearance(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
        await ShowToast("Appearance settings saved!", true);
    }

    private async Task ShowToast(string message, bool success)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toast = new ToastInfo(message, success ? "toast-success" : "toast-error");
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toast = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private record ToastInfo(string Message, string CssClass);
}

@using sv_fce9d96ce083410f87948881c81a6a9f.Models

<section class="settings-section">
    <h2>Profile</h2>

    <div class="avatar-area">
        <img src="@_displayName_AvatarUrl" alt="Avatar" class="avatar-preview" />
        <span class="avatar-url-display">@_displayName_AvatarUrl</span>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" class="form-input" @bind="_displayName" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" class="form-input" @bind="_email" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" class="form-input form-textarea" @bind="_bio" rows="4"></textarea>
    </div>

    <div class="form-group">
        <label for="avatarUrl">Avatar URL</label>
        <input id="avatarUrl" type="url" class="form-input" @bind="_displayName_AvatarUrl" />
    </div>

    <div class="button-row">
        <button class="btn btn-primary" @onclick="HandleSave" disabled="@(!HasChanges)">Save Changes</button>
        <button class="btn btn-secondary" @onclick="HandleDiscard" disabled="@(!HasChanges)">Discard Changes</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = null!;
    [Parameter, EditorRequired] public UserProfile SavedProfile { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }
    [Parameter, EditorRequired] public EventCallback OnDiscard { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _displayName_AvatarUrl = "";
    private string _bio = "";

    private bool HasChanges =>
        _displayName != SavedProfile.DisplayName ||
        _email != SavedProfile.Email ||
        _displayName_AvatarUrl != SavedProfile.AvatarUrl ||
        _bio != SavedProfile.Bio;

    protected override void OnParametersSet()
    {
        _displayName = Profile.DisplayName;
        _email = Profile.Email;
        _displayName_AvatarUrl = Profile.AvatarUrl;
        _bio = Profile.Bio;
    }

    private async Task HandleSave()
    {
        var updated = new UserProfile(_displayName, _email, _displayName_AvatarUrl, _bio);
        await OnSave.InvokeAsync(updated);
    }

    private async Task HandleDiscard()
    {
        _displayName = SavedProfile.DisplayName;
        _email = SavedProfile.Email;
        _displayName_AvatarUrl = SavedProfile.AvatarUrl;
        _bio = SavedProfile.Bio;
        await OnDiscard.InvokeAsync();
    }
}

@using sv_fce9d96ce083410f87948881c81a6a9f.Models

<section class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-row">
            <span>Email Notifications</span>
            <label class="switch">
                <input type="checkbox" checked="@_emailNotifications"
                       @onchange="e => _emailNotifications = (bool)(e.Value ?? false)" />
                <span class="slider"></span>
            </label>
        </label>

        <label class="toggle-row">
            <span>Push Notifications</span>
            <label class="switch">
                <input type="checkbox" checked="@_pushNotifications"
                       @onchange="e => _pushNotifications = (bool)(e.Value ?? false)" />
                <span class="slider"></span>
            </label>
        </label>

        <label class="toggle-row">
            <span>Weekly Digest</span>
            <label class="switch">
                <input type="checkbox" checked="@_weeklyDigest"
                       @onchange="e => _weeklyDigest = (bool)(e.Value ?? false)" />
                <span class="slider"></span>
            </label>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in AllChannels)
        {
            var isMuted = _mutedChannels.Contains(channel);
            <label class="channel-item">
                <input type="checkbox" checked="@isMuted"
                       @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                <span class="channel-name">#@channel</span>
                <span class="channel-status @(isMuted ? "muted" : "active")">
                    @(isMuted ? "Muted" : "Active")
                </span>
            </label>
        }
    </div>

    <div class="button-row">
        <button class="btn btn-primary" @onclick="HandleSave">Save Preferences</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = null!;
    [Parameter, EditorRequired] public List<string> AllChannels { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = [];

    protected override void OnParametersSet()
    {
        _emailNotifications = Prefs.EmailNotifications;
        _pushNotifications = Prefs.PushNotifications;
        _weeklyDigest = Prefs.WeeklyDigest;
        _mutedChannels = new List<string>(Prefs.MutedChannels);
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task HandleSave()
    {
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, new List<string>(_mutedChannels));
        await OnSave.InvokeAsync(updated);
    }
}

@using sv_fce9d96ce083410f87948881c81a6a9f.Models

<section class="settings-section">
    <h2>Security</h2>

    <!-- Change Password -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>🔑 Change Password</span>
            <span class="expand-icon">@(_passwordExpanded ? "▲" : "▼")</span>
        </button>
        @if (_passwordExpanded)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPwd">Current Password</label>
                    <input id="currentPwd" type="password" class="form-input" @bind="_currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPwd">New Password</label>
                    <input id="newPwd" type="password" class="form-input" @bind="_newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPwd">Confirm Password</label>
                    <input id="confirmPwd" type="password" class="form-input" @bind="_confirmPassword" />
                </div>
                @if (_passwordError is not null)
                {
                    <p class="field-error">@_passwordError</p>
                }
                <div class="button-row">
                    <button class="btn btn-primary" @onclick="HandleChangePassword">Update Password</button>
                </div>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="two-factor-area">
        <div class="toggle-row">
            <span>
                Two-Factor Authentication
                <span class="status-badge @(Security.TwoFactorEnabled ? "badge-enabled" : "badge-disabled")">
                    @(Security.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </span>
            <label class="switch">
                <input type="checkbox" checked="@Security.TwoFactorEnabled"
                       @onchange="e => OnToggle2FA.InvokeAsync((bool)(e.Value ?? false))" />
                <span class="slider"></span>
            </label>
        </div>
        @if (Security.LastPasswordChange.HasValue)
        {
            <p class="help-text">Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <h3>Active Sessions</h3>
    <div class="sessions-table-wrapper">
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Security.Sessions)
                {
                    var isCurrent = session.Id == CurrentSessionId;
                    <tr class="@(isCurrent ? "current-session" : "")">
                        <td>
                            @session.Device
                            @if (isCurrent)
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                        <td>@session.Location</td>
                        <td>@FormatLastActive(session.LastActive)</td>
                        <td>
                            @if (!isCurrent)
                            {
                                <button class="btn btn-danger btn-sm"
                                        @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (_sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="button-row">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</section>

@code {
    [Parameter, EditorRequired] public SecuritySettings Security { get; set; } = null!;
    [Parameter, EditorRequired] public string CurrentSessionId { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter, EditorRequired] public EventCallback<bool> OnToggle2FA { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;

    private ActiveSession? _sessionToRevoke;

    private async Task HandleChangePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (_newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordExpanded = false;
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@using sv_fce9d96ce083410f87948881c81a6a9f.Models

<section class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme -->
