        <p>This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Theme: @_theme · Font: @_fontSize · Language: @_language</p>
            <button class="btn btn-primary btn-preview">Sample Button</button>
        </div>
    </div>

    <div class="button-row">
        <button class="btn btn-primary" @onclick="HandleSave">Save</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Appearance { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Portuguese"];

    private string PreviewThemeClass => _theme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontClass => _fontSize switch
    {
        "Small" => "preview-font-small",
        "Large" => "preview-font-large",
        _ => "preview-font-medium"
    };

    protected override void OnParametersSet()
    {
        _theme = Appearance.Theme;
        _fontSize = Appearance.FontSize;
        _language = Appearance.Language;
        _compactMode = Appearance.CompactMode;
    }

    private async Task HandleSave()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
    }
}

