@using sv_fce9d96ce083410f87948881c81a6a9f.Models

<section class="settings-section">
    <h2>Profile</h2>

    <div class="avatar-area">
        <img src="@_displayName_AvatarUrl" alt="Avatar" class="avatar-preview" />
        <span class="avatar-url-display">@_displayName_AvatarUrl</span>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" class="form-input" @bind="_displayName" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" class="form-input" @bind="_email" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" class="form-input form-textarea" @bind="_bio" rows="4"></textarea>
    </div>

    <div class="form-group">
        <label for="avatarUrl">Avatar URL</label>
        <input id="avatarUrl" type="url" class="form-input" @bind="_displayName_AvatarUrl" />
    </div>

    <div class="button-row">
        <button class="btn btn-primary" @onclick="HandleSave" disabled="@(!HasChanges)">Save Changes</button>
        <button class="btn btn-secondary" @onclick="HandleDiscard" disabled="@(!HasChanges)">Discard Changes</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = null!;
    [Parameter, EditorRequired] public UserProfile SavedProfile { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }
    [Parameter, EditorRequired] public EventCallback OnDiscard { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _displayName_AvatarUrl = "";
    private string _bio = "";

    private bool HasChanges =>
        _displayName != SavedProfile.DisplayName ||
        _email != SavedProfile.Email ||
        _displayName_AvatarUrl != SavedProfile.AvatarUrl ||
        _bio != SavedProfile.Bio;

    protected override void OnParametersSet()
    {
        _displayName = Profile.DisplayName;
        _email = Profile.Email;
        _displayName_AvatarUrl = Profile.AvatarUrl;
        _bio = Profile.Bio;
    }

    private async Task HandleSave()
    {
        var updated = new UserProfile(_displayName, _email, _displayName_AvatarUrl, _bio);
        await OnSave.InvokeAsync(updated);
    }

    private async Task HandleDiscard()
    {
        _displayName = SavedProfile.DisplayName;
        _email = SavedProfile.Email;
        _displayName_AvatarUrl = SavedProfile.AvatarUrl;
        _bio = SavedProfile.Bio;
        await OnDiscard.InvokeAsync();
    }
}

