.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.1s;
}

.channel-item:hover {
    background: #f8f9fa;
}

.channel-name {
    flex: 1;
    font-weight: 500;
    color: #333;
}

.channel-status {
    font-size: 0.8rem;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
}

.channel-status.muted {
    background: #fff3cd;
    color: #856404;
}

.channel-status.active {
    background: #d1e7dd;
    color: #0f5132;
}

